// Place in Zabbix frontend under Configuration → Event correlation → Correlation rules
{
  "name": "Silence Zabbix agent flaps on test VMs",
  "enabled": true,
  "conditions": [
    {"condition": "trigger.name", "operator": "contains", "value": "Zabbix agent is not available"},
    {"condition": "host.name", "operator": "like", "value": "*-test-vm-*"},
    {"condition": "trigger.severity", "operator": "in", "value": [3,4,5]} // 3=Average,4=Warning,5=Information
  ],
  "actions": [
    {"action": "suppress", "duration": 1440} // suppress alerts for 1440 minutes (1 day)
  ],
  "max_events": 0
}
